#!/usr/bin/env python3
"""Compute the deterministic source-gate reference values for CSX-299_Q2."""

from __future__ import annotations

import html
import json
import math
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-299_Q2"
PACKAGE_ID = "CSX-299"
TARGET_FAMILY = "patagonian_dust_source_gate_consistency_proof"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Patagonian_dust_streamers.json",
    "data/event_reports/event_reports_004_NASA_EO_Patagonian_Dust_Streamers.html",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
]

DRY_MEAN_MM_THRESHOLD = 0.1
TRANSPORT_KM_THRESHOLD = 120


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig", errors="replace")


def clean_html_text(text: str) -> str:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", text)
    text = re.sub(r"(?is)<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def text_has_any(text: str, needles: list[str]) -> bool:
    lower_text = text.lower()
    return any(needle.lower() in lower_text for needle in needles)


def text_has_all(text: str, needles: list[str]) -> bool:
    lower_text = text.lower()
    return all(needle.lower() in lower_text for needle in needles)


def int_gate(value: bool) -> int:
    return 1 if value else 0


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def build_output() -> dict[str, Any]:
    task_dir = Path(__file__).resolve().parent
    workspace = task_dir.parents[2]
    package_dir = workspace / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID

    event_json = read_json(package_dir / SOURCE_FILES[0])
    anchor = read_json(package_dir / SOURCE_FILES[1])
    report_text = clean_html_text(read_text(package_dir / SOURCE_FILES[2]))
    era5_stats = read_json(package_dir / SOURCE_FILES[3])["stats"]
    gpm_stats = read_json(package_dir / SOURCE_FILES[4])["stats"]
    chirps_stats = read_json(package_dir / SOURCE_FILES[5])["stats"]
    embedding = read_json(package_dir / SOURCE_FILES[6])

    source_flags = {
        "primary_source_lake": text_has_any(report_text, ["The primary source of dust is Lago Colhu"]),
        "dry_season_evaporation": text_has_all(report_text, ["dry season", "evaporation"]),
        "exposed_loose_silt": text_has_any(report_text, ["loose silt exposed at the surface"]),
        "ground_lifted_streamers": text_has_any(report_text, ["dust lifted off from the ground"]),
        "wind_aligned_streamers": text_has_any(report_text, ["aligned with the wind direction"]),
    }
    source_flags_present = sum(int_gate(value) for value in source_flags.values())

    distance_match = re.search(r"more than\s+([0-9]+)\s+kilometers", report_text, re.IGNORECASE)
    transport_km_lower_bound = int(distance_match.group(1)) if distance_match else 0
    report_context_date = "2020-03-07" if re.search(r"March\s+7", report_text, flags=re.IGNORECASE) else "report_context"
    evidence_windows = {
        "event_window": {
            "start": anchor["temporal_window"]["start_date"],
            "end": anchor["temporal_window"]["end_date"],
        },
        "precip_wind_window": {
            "start": read_json(package_dir / SOURCE_FILES[3])["start"],
            "end": read_json(package_dir / SOURCE_FILES[3])["end"],
        },
        "transport_report_context_date": report_context_date,
    }

    precip_means = {
        "gpm_mean_mm": gpm_stats["gpm_event_precip_mm_mean"],
        "chirps_mean_mm": chirps_stats["chirps_event_precip_mm_mean"],
    }
    dry_precip_product_count = sum(
        1 for value in precip_means.values() if value <= DRY_MEAN_MM_THRESHOLD
    )

    source_gate_observed = int_gate(
        source_flags["primary_source_lake"]
        and source_flags["dry_season_evaporation"]
        and source_flags["exposed_loose_silt"]
    )
    lift_gate = int_gate(source_flags["ground_lifted_streamers"])
    wind_align_gate = int_gate(source_flags["wind_aligned_streamers"])
    dry_precip_gate = int_gate(dry_precip_product_count == len(precip_means))
    transport_gate = int_gate(transport_km_lower_bound >= TRANSPORT_KM_THRESHOLD)

    observed_score = (
        source_gate_observed * lift_gate * wind_align_gate * dry_precip_gate * transport_gate
    )
    counterfactual_score = 0 * lift_gate * wind_align_gate * dry_precip_gate * transport_gate

    annual_change_mean = embedding["stats"]["alphaearth_1_minus_cosine_mean"]
    annual_change_max = embedding["stats"]["alphaearth_1_minus_cosine_max"]
    annual_change_ratio = annual_change_max / annual_change_mean
    wind_speed_from_components = math.hypot(
        era5_stats["u_component_of_wind_10m_mean"],
        era5_stats["v_component_of_wind_10m_mean"],
    )

    primary_gt = {
        "evidence_windows": evidence_windows,
        "answer": "source_gate_fail",
        "observed_chain_score": observed_score,
        "counterfactual_chain_score": counterfactual_score,
        "source_flags_present": source_flags_present,
        "dry_precip_product_count": dry_precip_product_count,
        "transport_distance_km_lower_bound": transport_km_lower_bound,
        "annual_change_max_to_mean_ratio": rounded(annual_change_ratio, 2),
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer schema",
                "points": 3,
                "description": "Returns compact JSON with the required label, both scores, source flag count, dry-precipitation count, transport distance, and annual-change ratio.",
                "partial_credit": "Award 1-2 points when the calculation is recoverable but one field is missing or renamed unclearly.",
            },
            {
                "name": "Source and lifting gates",
                "points": 4,
                "description": "Counts all five observed source-chain indicators and forms the observed source, lift, and wind-alignment gates correctly.",
                "partial_credit": "Award 1-3 points for a partial source-chain count or for omitting one of the lift or wind-alignment gates.",
            },
            {
                "name": "Precipitation and transport thresholds",
                "points": 4,
                "description": "Applies the <=0.1 mm event-day mean threshold to both precipitation products and the >=120 km threshold to the report-context transport lower bound.",
                "partial_credit": "Award 1-3 points for using the right variables with one threshold, rounding, or count error.",
            },
            {
                "name": "Multiplicative proof",
                "points": 4,
                "description": "Uses score = source_gate * lift_gate * wind_align_gate * dry_precip_gate * transport_gate, giving observed_chain_score = 1 and counterfactual_chain_score = 0.",
                "partial_credit": "Award 1-3 points if the formula is described but one score is wrong or the counterfactual source gate is not forced to zero.",
            },
            {
                "name": "Timing check",
                "points": 2,
                "description": "Reports the annual surface-change max-to-mean ratio near 17.16 and treats it as a year-scale timing check.",
                "partial_credit": "Award 1 point for computing the ratio but overstating its role in the event-day gate.",
            },
            {
                "name": "Computed consequence",
                "points": 2,
                "description": "Uses the fail label only because the counterfactual score is below the pass score of 1.",
                "partial_credit": "Award 1 point for the right label without a clear score comparison.",
            },
            {
                "name": "Scope control",
                "points": 1,
                "description": "Keeps the final sentence to the computed source-gate consequence and does not add impact or process narration.",
                "partial_credit": "Award no more than 1 point here for any prose-only explanation.",
            },
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "target_family": TARGET_FAMILY,
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "observed_chain_score": {"target": observed_score, "absolute_tolerance": 0},
            "counterfactual_chain_score": {"target": counterfactual_score, "absolute_tolerance": 0},
            "source_flags_present": {"target": source_flags_present, "absolute_tolerance": 0},
            "dry_precip_product_count": {"target": dry_precip_product_count, "absolute_tolerance": 0},
            "transport_distance_km_lower_bound": {"target": transport_km_lower_bound, "absolute_tolerance": 0},
            "annual_change_max_to_mean_ratio": {
                "target": rounded(annual_change_ratio, 2),
                "absolute_tolerance": 0.02,
            },
        },
        "event": {
            "event_name": event_json["event_name"],
            "hazard_family": event_json["hazard_family"],
            "event_date_or_window": (
                f"{anchor['temporal_window']['start_date']} to "
                f"{anchor['temporal_window']['end_date']}"
            ),
            "location": anchor["spatial_window"]["location_text"],
        },
        "decision_rule": {
            "formula": "score = source_gate * lift_gate * wind_align_gate * dry_precip_gate * transport_gate",
            "thresholds": {
                "dry_mean_mm_max": DRY_MEAN_MM_THRESHOLD,
                "transport_distance_km_min": TRANSPORT_KM_THRESHOLD,
                "pass_score": 1,
            },
            "evidence_windows": evidence_windows,
            "counterfactual_source_gate": 0,
            "computed_consequence": "counterfactual score below 1 means the source-gate test fails",
        },
        "key_values": {
            "source_flags": source_flags,
            "transport_report_context_date": report_context_date,
            "gates": {
                "observed_source_gate": source_gate_observed,
                "counterfactual_source_gate": 0,
                "lift_gate": lift_gate,
                "wind_align_gate": wind_align_gate,
                "dry_precip_gate": dry_precip_gate,
                "transport_gate": transport_gate,
            },
            "precipitation_means_mm": precip_means,
            "wind_speed_from_mean_components_m_s": rounded(wind_speed_from_components, 3),
            "annual_change": {
                "pre_year": embedding["pre_year"],
                "post_year": embedding["post_year"],
                "mean_1_minus_cosine": annual_change_mean,
                "max_1_minus_cosine": annual_change_max,
                "max_to_mean_ratio": annual_change_ratio,
            },
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "All values are parsed from local CSX-299 package records.",
        },
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    output = build_output()
    (task_dir / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
